(()=>{'use strict';const root=document.documentElement,media=matchMedia('(prefers-color-scheme:dark)');let theme='system',lang='es';try{theme=localStorage.getItem('hefesto-theme')||'system';lang=localStorage.getItem('hefesto-language')||'es'}catch{}if(!['light','dark','system'].includes(theme))theme='system';if(!['es','en'].includes(lang))lang='es';function applyTheme(){root.dataset.theme=theme==='system'?(media.matches?'dark':'light'):theme;document.querySelectorAll('[data-theme-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.themeChoice===theme)))}function applyLang(){root.lang=lang;document.querySelectorAll('[data-es]').forEach(el=>el.textContent=el.dataset[lang]);document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));updateStatus()}function updateStatus(){const status=document.querySelector('#filter-status');if(!status)return;status.textContent=document.querySelectorAll('.feature:not([hidden])').length+(lang==='es'?' funcionalidades visibles':' visible features')}document.querySelectorAll('[data-theme-choice]').forEach(b=>b.addEventListener('click',()=>{theme=b.dataset.themeChoice;try{localStorage.setItem('hefesto-theme',theme)}catch{}applyTheme()}));media.addEventListener('change',applyTheme);document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{lang=b.dataset.lang;try{localStorage.setItem('hefesto-language',lang)}catch{}applyLang()}));document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('.feature').forEach(x=>x.hidden=b.dataset.filter!=='all'&&b.dataset.filter!==x.dataset.category);updateStatus()}));applyTheme();applyLang();if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion:reduce)').matches){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('enter');io.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.feature,.gallery figure,.services article').forEach(el=>io.observe(el))}})();
